def link(url,text,cls='button teal'):
 return f'<a class="{cls}" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
def cta(title='Your next shipment starts here.',text='Tell us what you’re moving. Let’s find the right way forward.'):
 return f'<section class="section page-cta"><div><div class="eyebrow teal-text">LET’S MAKE YOUR NEXT MOVE</div><h2>{title}</h2><p>{text}</p></div>{link("/get-quote/","Get a shipping quote")}</section>'
def intro(eyebrow,title,desc,crumb,photo=False):
 return f'<section class="inner-hero {"with-photo" if photo else ""}"><div class="inner-hero-wrap"><div class="breadcrumbs"><a href="/">Home</a><span aria-hidden="true">/</span><span>{crumb}</span></div><div class="eyebrow"><span class="line"></span>{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div><div class="inner-route" aria-hidden="true">CHINA <span>⟶</span> NIGERIA</div></section>'
def cards(items,cls='detail-grid'):
 return '<div class="'+cls+'">'+''.join(f'<article class="detail-card"><span class="card-number">0{i+1}</span><h3>{title}</h3><p>{text}</p></article>' for i,(title,text) in enumerate(items))+'</div>'
def faq(items):
 return '<div class="faq-list">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><div><p>{a}</p></div></details>' for q,a in items)+'</div>'
