def render(route,title,desc,body):
 head=re.sub(r'<title>.*?</title>',f'<title>{escape(title)} | Bright Ocean Logistics</title>',HEAD)
 head=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{escape(desc,quote=True)}">',head)
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if route==url or (url=='/services/' and route.startswith('/services/')) else '')+f'>{label}</a>' for url,label in NAV)
 header=f'<a class="skip-link" href="#main-content">Skip to content</a><div class="topbar"><span>Connecting China and Nigeria. Moving your business forward.</span><a href="mailto:bw020930@gmail.com">bw020930@gmail.com <span>↗</span></a></div><header><a class="brand" href="/" aria-label="Bright Ocean home"><img src="/assets/logo.png" width="180" height="98" alt="Bright Ocean Logistics"></a><nav id="main-nav" aria-label="Main navigation">{nav}</nav><a class="button dark nav-cta" href="/get-quote/">Get a shipping quote <span>↗</span></a><button class="menu-toggle" aria-label="Open menu" aria-expanded="false" aria-controls="main-nav"><span class="menu-bars" aria-hidden="true"></span></button></header>'
 footer='<footer><div class="footer-top"><div><a class="footer-brand" href="/">Bright Ocean<span>LOGISTICS</span></a><p>Moving cargo. Connecting possibilities.</p><a class="footer-email" href="mailto:bw020930@gmail.com">bw020930@gmail.com</a></div><div><span>EXPLORE</span><a href="/about/">About Bright Ocean</a><a href="/services/sea-shipping/">Sea shipping</a><a href="/services/air-freight/">Air freight</a><a href="/locations/">Our locations</a></div><div><span>HOW CAN WE HELP?</span><a href="/shipping-guide/">Shipping guide</a><a href="/faq/">Common questions</a><a href="/get-quote/">Request a quote</a><a href="/contact/">Contact our team</a></div><div><span>FOLLOW THE JOURNEY</span><a href="https://www.instagram.com/bright_ocean_logistice/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.tiktok.com/@brightocean123" target="_blank" rel="noopener">TikTok ↗</a><a href="tel:+2348060227854">+234 806 022 7854</a></div></div><div class="footer-bottom"><span>© <span id="year">2026</span> Bright Ocean Logistics Co. Services LTD</span><a href="#top">Back to top ↑</a><span>CHINA → NIGERIA</span></div></footer>'
 return '<!doctype html>\n<html lang="en"><head>'+head+'</head><body id="top" class="'+('home-page' if route=='/' else 'inner-page')+'">'+header+'<main id="main-content" tabindex="-1">'+body+'</main>'+footer+'<script src="/app.js" defer></script></body></html>\n'
